-- ===== 0001_schema =====
-- DairyFarmDesk schema. Run in the Supabase SQL editor in order: 0001, 0002, 0003, 0004, then seed.sql (optional)


create type user_role as enum ('admin','manager');
create type animal_type as enum ('Cow','Buffalo','Calf','Heifer','Bull');
create type animal_breed as enum ('HF','Jersey','Gir','Sahiwal','Murrah','Crossbred','Other');
create type animal_status as enum ('Lactating','Dry','Pregnant','Sold','Dead');
create type shift_t as enum ('Morning','Evening');
create type customer_type as enum ('Home delivery','Dairy-cooperative','Hotel','Shop');
create type pay_mode as enum ('Cash','UPI','Bank');
create type expense_category as enum ('Feed','Labour/Salary','Electricity','Fuel','Transport','Repairs','Other');
create type medical_type as enum ('Treatment','Vaccination','Deworming','Artificial Insemination','Pregnancy check','Checkup','Other');

create table settings (
  id int primary key default 1 check (id = 1),
  farm_name text not null default 'DairyFarmDesk',
  logo_url text,
  default_rate numeric(8,2) not null default 55,
  manager_edit_days int not null default 2,
  language text not null default 'en',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
insert into settings (id) values (1);

create table profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null default '',
  email text,
  phone text,
  role user_role not null default 'manager',
  active boolean not null default true,
  created_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table animals (
  id uuid primary key default gen_random_uuid(),
  tag_no text not null unique,
  name text,
  type animal_type not null default 'Cow',
  breed animal_breed not null default 'Crossbred',
  dob date,
  purchase_date date,
  purchase_price numeric(12,2),
  source text,
  status animal_status not null default 'Lactating',
  photo_url text,
  notes text,
  archived boolean not null default false,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table milk_production (
  id uuid primary key default gen_random_uuid(),
  animal_id uuid not null references animals(id),
  entry_date date not null,
  shift shift_t not null,
  litres numeric(6,2) not null check (litres >= 0),
  fat numeric(4,2),
  snf numeric(4,2),
  notes text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (animal_id, entry_date, shift)
);
create index on milk_production (entry_date);

create table customers (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  phone text,
  area text,
  type customer_type not null default 'Home delivery',
  default_rate numeric(8,2) not null default 55,
  default_morning_litres numeric(6,2) not null default 0,
  default_evening_litres numeric(6,2) not null default 0,
  opening_balance numeric(12,2) not null default 0,
  active boolean not null default true,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table milk_sales (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null references customers(id),
  entry_date date not null,
  shift shift_t not null,
  litres numeric(6,2) not null check (litres >= 0),
  rate numeric(8,2) not null check (rate >= 0),
  amount numeric(12,2) generated always as (round(litres * rate, 2)) stored,
  notes text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (customer_id, entry_date, shift)
);
create index on milk_sales (entry_date);

create table customer_payments (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null references customers(id),
  entry_date date not null,
  amount numeric(12,2) not null check (amount > 0),
  mode pay_mode not null default 'Cash',
  note text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on customer_payments (entry_date);

create table expenses (
  id uuid primary key default gen_random_uuid(),
  entry_date date not null,
  category expense_category not null default 'Feed',
  item_name text not null,
  quantity numeric(10,2),
  unit text,
  rate numeric(10,2),
  amount numeric(12,2) not null check (amount >= 0),
  supplier text,
  pay_mode pay_mode not null default 'Cash',
  bill_url text,
  notes text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on expenses (entry_date);

create table medical_records (
  id uuid primary key default gen_random_uuid(),
  animal_id uuid not null references animals(id),
  entry_date date not null,
  type medical_type not null default 'Treatment',
  symptoms text,
  medicine text,
  dose text,
  vet_name text,
  cost numeric(12,2) not null default 0,
  withdrawal_days int not null default 0 check (withdrawal_days >= 0),
  next_due_date date,
  notes text,
  photo_url text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on medical_records (animal_id, entry_date);
create index on medical_records (next_due_date);

create table audit_log (
  id uuid primary key default gen_random_uuid(),
  user_id uuid,
  user_name text,
  action text not null,
  table_name text not null,
  record_id uuid,
  old_data jsonb,
  new_data jsonb,
  created_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on audit_log (created_at desc);


-- ===== 0002_helpers =====
-- Helpers and audit/updated_at triggers

create or replace function today_ist() returns date language sql stable as
$$ select (now() at time zone 'Asia/Kolkata')::date $$;

create or replace function is_admin() returns boolean
language sql stable security definer set search_path = stg as
$$ select coalesce((select role = 'admin' and active from profiles where id = auth.uid()), false) $$;

create or replace function is_staff() returns boolean
language sql stable security definer set search_path = stg as
$$ select coalesce((select active from profiles where id = auth.uid()), false) $$;

-- Manager may touch a row only if its date is within the last N days (settings.manager_edit_days). Admin always.
create or replace function manager_can_edit(d date) returns boolean
language sql stable security definer set search_path = stg as
$$ select is_admin() or (is_staff() and d >= today_ist() - (select manager_edit_days from settings where id = 1)) $$;

create or replace function set_updated_at() returns trigger language plpgsql as
$$ begin new.updated_at = now(); return new; end $$;

create or replace function audit_trigger() returns trigger
language plpgsql security definer set search_path = stg as
$$
declare
  uname text;
  rid uuid;
begin
  select full_name into uname from profiles where id = auth.uid();
  if (tg_table_name = 'settings') then
    rid := null;
  elsif (tg_op = 'DELETE') then
    rid := old.id;
  else
    rid := new.id;
  end if;
  insert into audit_log (user_id, user_name, action, table_name, record_id, old_data, new_data, created_by)
  values (auth.uid(), uname, tg_op, tg_table_name, rid,
          case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end,
          case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end,
          auth.uid());
  if (tg_op = 'DELETE') then return old; end if;
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['profiles','animals','milk_production','customers','milk_sales','customer_payments','expenses','medical_records','settings']
  loop
    execute format('create trigger trg_%1$s_updated before update on %1$s for each row execute function set_updated_at()', t);
    execute format('create trigger trg_%1$s_audit after insert or update or delete on %1$s for each row execute function audit_trigger()', t);
  end loop;
end $$;


-- ===== 0003_rls =====
-- Row Level Security policies

alter table profiles enable row level security;
alter table settings enable row level security;
alter table animals enable row level security;
alter table milk_production enable row level security;
alter table customers enable row level security;
alter table milk_sales enable row level security;
alter table customer_payments enable row level security;
alter table expenses enable row level security;
alter table medical_records enable row level security;
alter table audit_log enable row level security;

-- profiles: own row readable, admin all. Managers are created by the Edge Function (service role).
create policy profiles_select on profiles for select using (id = auth.uid() or is_admin());
create policy profiles_admin_write on profiles for all using (is_admin()) with check (is_admin());

-- settings: any staff read, admin update
create policy settings_select on settings for select using (is_staff());
create policy settings_admin_write on settings for update using (is_admin()) with check (is_admin());

-- animals: staff read, admin add/edit/archive/delete
create policy animals_select on animals for select using (is_staff());
create policy animals_admin_write on animals for all using (is_admin()) with check (is_admin());

-- customers: staff read/insert/update, admin delete
create policy customers_select on customers for select using (is_staff());
create policy customers_insert on customers for insert with check (is_staff());
create policy customers_update on customers for update using (is_staff()) with check (is_staff());
create policy customers_delete on customers for delete using (is_admin());

-- Dated tables: staff read; insert/update only inside edit window (admin always); delete admin only
do $$
declare t text;
begin
  foreach t in array array['milk_production','milk_sales','customer_payments','expenses','medical_records']
  loop
    execute format('create policy %1$s_select on %1$s for select using (is_staff())', t);
    execute format('create policy %1$s_insert on %1$s for insert with check (manager_can_edit(entry_date))', t);
    execute format('create policy %1$s_update on %1$s for update using (manager_can_edit(entry_date)) with check (manager_can_edit(entry_date))', t);
    execute format('create policy %1$s_delete on %1$s for delete using (is_admin())', t);
  end loop;
end $$;

-- audit log: admin read only (rows are written by the security definer trigger)
create policy audit_select on audit_log for select using (is_admin());



-- ===== 0004_views =====
-- Admin-only reporting functions (profit etc.). Managers get an error.

create or replace function customer_ledger()
returns table (customer_id uuid, name text, phone text, opening numeric, supplied numeric, paid numeric, outstanding numeric)
language sql stable security definer set search_path = stg as $$
  select c.id, c.name, c.phone, c.opening_balance,
    coalesce((select sum(amount) from milk_sales s where s.customer_id = c.id),0),
    coalesce((select sum(amount) from customer_payments p where p.customer_id = c.id),0),
    c.opening_balance
      + coalesce((select sum(amount) from milk_sales s where s.customer_id = c.id),0)
      - coalesce((select sum(amount) from customer_payments p where p.customer_id = c.id),0)
  from customers c where is_staff();
$$;

create or replace function admin_summary(from_d date, to_d date)
returns table (litres numeric, sold_litres numeric, revenue numeric, expenses numeric, medical numeric, profit numeric, cost_per_litre numeric)
language plpgsql stable security definer set search_path = stg as $$
declare l numeric; sl numeric; r numeric; e numeric; m numeric;
begin
  if not is_admin() then raise exception 'admin only'; end if;
  select coalesce(sum(litres),0) into l from milk_production where entry_date between from_d and to_d;
  select coalesce(sum(litres),0), coalesce(sum(amount),0) into sl, r from milk_sales where entry_date between from_d and to_d;
  select coalesce(sum(amount),0) into e from expenses where entry_date between from_d and to_d;
  select coalesce(sum(cost),0) into m from medical_records where entry_date between from_d and to_d;
  return query select l, sl, r, e, m, r - e - m, case when l > 0 then round((e + m) / l, 2) else 0 end;
end $$;

create or replace function daily_series(from_d date, to_d date)
returns table (d date, litres numeric, sold numeric, revenue numeric, expense numeric)
language plpgsql stable security definer set search_path = stg as $$
begin
  if not is_admin() then raise exception 'admin only'; end if;
  return query
  select g::date,
    coalesce((select sum(litres) from milk_production where entry_date = g::date),0),
    coalesce((select sum(litres) from milk_sales where entry_date = g::date),0),
    coalesce((select sum(amount) from milk_sales where entry_date = g::date),0),
    coalesce((select sum(amount) from expenses where entry_date = g::date),0)
  from generate_series(from_d, to_d, interval '1 day') g order by 1;
end $$;

-- Animals currently under milk withdrawal (any staff)
create or replace function animals_under_withdrawal()
returns table (animal_id uuid, tag_no text, medicine text, until date)
language sql stable security definer set search_path = stg as $$
  select a.id, a.tag_no, m.medicine, (m.entry_date + m.withdrawal_days)
  from medical_records m join animals a on a.id = m.animal_id
  where is_staff() and m.withdrawal_days > 0 and today_ist() <= m.entry_date + m.withdrawal_days;
$$;

grant execute on function customer_ledger(), animals_under_withdrawal() to authenticated;
grant execute on function admin_summary(date,date), daily_series(date,date) to authenticated;


